-- =============================================================================================
-- Hand-written below this line: integrity rules, membership scope check, row-level security and
-- grants for the property structure. See docs/architecture/DATA_MODEL.md section 3.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- Data integrity
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "properties" ADD CONSTRAINT "properties_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120);
ALTER TABLE "properties" ADD CONSTRAINT "properties_code_format"
  CHECK ("code" ~ '^[A-Z0-9]+(-[A-Z0-9]+)*$' AND length("code") BETWEEN 2 AND 20);
ALTER TABLE "properties" ADD CONSTRAINT "properties_country_code_format"
  CHECK ("country_code" ~ '^[A-Z]{2}$');
ALTER TABLE "properties" ADD CONSTRAINT "properties_currency_format"
  CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "properties" ADD CONSTRAINT "properties_time_zone_present"
  CHECK (length(btrim("time_zone")) > 0);
ALTER TABLE "properties" ADD CONSTRAINT "properties_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

ALTER TABLE "buildings" ADD CONSTRAINT "buildings_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120);
ALTER TABLE "buildings" ADD CONSTRAINT "buildings_code_format"
  CHECK ("code" ~ '^[A-Z0-9]+(-[A-Z0-9]+)*$' AND length("code") BETWEEN 1 AND 20);
ALTER TABLE "buildings" ADD CONSTRAINT "buildings_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

ALTER TABLE "floors" ADD CONSTRAINT "floors_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 60);
ALTER TABLE "floors" ADD CONSTRAINT "floors_level_range"
  CHECK ("level" BETWEEN -20 AND 300);
ALTER TABLE "floors" ADD CONSTRAINT "floors_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

ALTER TABLE "units" ADD CONSTRAINT "units_number_trimmed"
  CHECK ("number" = btrim("number") AND length("number") BETWEEN 1 AND 40);
-- A floor only exists inside a building. Without this, MATCH SIMPLE would skip the floor foreign
-- key whenever building_id is NULL, letting a unit reference any floor id.
ALTER TABLE "units" ADD CONSTRAINT "units_floor_requires_building"
  CHECK ("floor_id" IS NULL OR "building_id" IS NOT NULL);
ALTER TABLE "units" ADD CONSTRAINT "units_area_positive"
  CHECK ("area_sqm" IS NULL OR "area_sqm" > 0);
ALTER TABLE "units" ADD CONSTRAINT "units_share_ratio_positive"
  CHECK ("share_ratio" IS NULL OR "share_ratio" > 0);
ALTER TABLE "units" ADD CONSTRAINT "units_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));
-- Unit numbers are unique per building, or per property for units without a building (villas).
-- Case-insensitive ("12B" = "12b"). NULLS NOT DISTINCT makes two building-less units with the
-- same number conflict too.
CREATE UNIQUE INDEX "units_number_unique"
  ON "units" ("property_id", "building_id", lower("number")) NULLS NOT DISTINCT;

ALTER TABLE "common_areas" ADD CONSTRAINT "common_areas_name_trimmed"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120);
ALTER TABLE "common_areas" ADD CONSTRAINT "common_areas_archive_consistent"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL));

-- ---------------------------------------------------------------------------------------------
-- Membership and invitation scopes: a PROPERTY/BUILDING/UNIT scope must name a row of the same
-- organisation. scope_id is polymorphic, so a foreign key cannot express this; a trigger does.
-- The function runs as the caller (not SECURITY DEFINER), under the caller's RLS context, which
-- for every allowed write is the membership's own organisation. Structure rows are never
-- deleted (no DELETE privilege), so a valid scope cannot dangle later.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app_assert_scope_in_organisation() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."scope_type" = 'ORGANISATION' THEN
    RETURN NEW; -- checked by the *_org_scope_matches constraints
  ELSIF NEW."scope_type" = 'PROPERTY' AND EXISTS (
    SELECT 1 FROM "properties" WHERE "organisation_id" = NEW."organisation_id" AND "id" = NEW."scope_id"
  ) THEN
    RETURN NEW;
  ELSIF NEW."scope_type" = 'BUILDING' AND EXISTS (
    SELECT 1 FROM "buildings" WHERE "organisation_id" = NEW."organisation_id" AND "id" = NEW."scope_id"
  ) THEN
    RETURN NEW;
  ELSIF NEW."scope_type" = 'UNIT' AND EXISTS (
    SELECT 1 FROM "units" WHERE "organisation_id" = NEW."organisation_id" AND "id" = NEW."scope_id"
  ) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'scope % % does not belong to organisation %',
    NEW."scope_type", NEW."scope_id", NEW."organisation_id"
    USING ERRCODE = 'foreign_key_violation';
END
$$;

CREATE TRIGGER "memberships_scope_in_organisation"
  BEFORE INSERT OR UPDATE OF "organisation_id", "scope_type", "scope_id" ON "memberships"
  FOR EACH ROW EXECUTE FUNCTION app_assert_scope_in_organisation();

CREATE TRIGGER "invitations_scope_in_organisation"
  BEFORE INSERT OR UPDATE OF "organisation_id", "scope_type", "scope_id" ON "invitations"
  FOR EACH ROW EXECUTE FUNCTION app_assert_scope_in_organisation();

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only, same pattern as organisations (MULTI_TENANCY 3.3).
-- Property-level scoping (a manager of P1 sees only P1) is enforced by the application's
-- permission engine on top of this.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "properties" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "properties" FORCE ROW LEVEL SECURITY;
CREATE POLICY "properties_select" ON "properties" FOR SELECT
  USING ("organisation_id" = app_current_organisation_id());
CREATE POLICY "properties_insert" ON "properties" FOR INSERT
  WITH CHECK ("organisation_id" = app_current_organisation_id());
CREATE POLICY "properties_update" ON "properties" FOR UPDATE
  USING ("organisation_id" = app_current_organisation_id())
  WITH CHECK ("organisation_id" = app_current_organisation_id());

ALTER TABLE "buildings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "buildings" FORCE ROW LEVEL SECURITY;
CREATE POLICY "buildings_select" ON "buildings" FOR SELECT
  USING ("organisation_id" = app_current_organisation_id());
CREATE POLICY "buildings_insert" ON "buildings" FOR INSERT
  WITH CHECK ("organisation_id" = app_current_organisation_id());
CREATE POLICY "buildings_update" ON "buildings" FOR UPDATE
  USING ("organisation_id" = app_current_organisation_id())
  WITH CHECK ("organisation_id" = app_current_organisation_id());

ALTER TABLE "floors" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "floors" FORCE ROW LEVEL SECURITY;
CREATE POLICY "floors_select" ON "floors" FOR SELECT
  USING ("organisation_id" = app_current_organisation_id());
CREATE POLICY "floors_insert" ON "floors" FOR INSERT
