-- ---------------------------------------------------------------------------------------------
-- Least privilege: read, create and update (including archive). No DELETE, no TRUNCATE.
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "properties", "buildings", "floors", "units", "common_areas" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "properties", "buildings", "floors", "units", "common_areas" TO veyra_app;
